#pragma once

#include "lob/Types.hpp"

#include <cstddef>
#include <functional>
#include <list>
#include <map>
#include <optional>
#include <unordered_map>
#include <vector>

namespace lob {

struct PriceLevelInfo {
    Price price{};
    Quantity totalQuantity{};
    std::size_t orderCount{};
};

// Single-instrument, price-time-priority limit order book.
class OrderBook {
public:
    // Adds a limit order. May match immediately against resting orders on the
    // opposite side; any unfilled remainder is handled per `tif`. Returns the
    // trades generated by this call, in execution order.
    std::vector<Trade> addLimitOrder(OrderId id, Side side, Price price, Quantity quantity,
                                      TimeInForce tif = TimeInForce::GTC);

    // Matches immediately against the book at any price; never rests.
    std::vector<Trade> addMarketOrder(OrderId id, Side side, Quantity quantity);

    // Removes a resting order. Returns false if no resting order has this id.
    bool cancelOrder(OrderId id);

    // Cancels the existing order and re-submits it as a new GTC limit order
    // with the given price/quantity. This loses time priority at its level,
    // matching typical exchange semantics for a price or quantity-increase change.
    std::vector<Trade> modifyOrder(OrderId id, Price newPrice, Quantity newQuantity);

    std::optional<Price> bestBid() const;
    std::optional<Price> bestAsk() const;

    // Aggregated view of up to maxLevels price levels, best price first.
    std::vector<PriceLevelInfo> depth(Side side, std::size_t maxLevels) const;

    bool hasOrder(OrderId id) const;
    std::size_t orderCount() const { return locations_.size(); }

private:
    using Level = std::list<Order>;
    using BidBook = std::map<Price, Level, std::greater<Price>>;
    using AskBook = std::map<Price, Level, std::less<Price>>;

    struct OrderLocation {
        Side side;
        Price price;
        Level::iterator it;
    };

    BidBook bids_;
    AskBook asks_;
    std::unordered_map<OrderId, OrderLocation> locations_;
    Timestamp clock_ = 0;

    Timestamp nextTimestamp() { return ++clock_; }

    // True if a taker on `takerSide` could fill `quantity` immediately given `limitPrice`.
    // Read-only: used to decide FOK orders before any mutation happens.
    bool canFullyFill(Side takerSide, Price limitPrice, Quantity quantity) const;

    // Matches a Buy taker against the ask book. `limitPrice` is std::nullopt for
    // market orders (matches at any price). Returns unfilled remainder.
    Quantity matchAgainstAsks(OrderId takerId, std::optional<Price> limitPrice, Quantity quantity,
                               std::vector<Trade>& trades);

    // Matches a Sell taker against the bid book. Mirror of matchAgainstAsks.
    Quantity matchAgainstBids(OrderId takerId, std::optional<Price> limitPrice, Quantity quantity,
                               std::vector<Trade>& trades);

    void insertResting(Side side, OrderId id, Price price, Quantity quantity);
};

} // namespace lob
